// Moore FSM, onehot->int state transition, explicitly named next
// state function. Synchronous reset to state A, active high.
module TopModule(input  clk, input  reset, input  in, output out);
  reg [1:0] state, next_state;
  reg       out_reg;
  always @(*) begin
    case (state)
      2'b00: begin next_state = 2'b00; out_reg = 1'b0; end
      2'b01: begin next_state = in ? 2'b01 : 2'b00; out_reg = 1'b0; end
      2'b10: begin next_state = in ? 2'b10 : 2'b01; out_reg = 1'b0; end
      2'b11: begin next_state = in ? 2'b00 : 2'b11; out_reg = 1'b1; end
    endcase
  end
  always @(posedge clk) begin
    if (reset) state <= 2'b00;
    else       state <= next_state;
  end
  assign out = out_reg;
endmodule

