    reg [1:0] state_vecs [0:3];
    reg [1:0] next_state_vecs [0:3];
    reg [1:0] state_vec;
    reg [1:0] next_state_vec;
    reg [1:0] next_state_vec_indexed;
    integer i;

    always @(*) begin
        state_vecs[0] = 2'b00;
        state_vecs[1] = 2'b01;
        state_vecs[2] = 2'b10;
        state_vecs[3] = 2'b11;
        next_state_vecs[0] = 2'b00;
        next_state_vecs[1] = 2'b01;
        next_state_vecs[2] = 2'b10;
        next_state_vecs[3] = 2'b11;
        next_state_comb[0] = 2'b00;
        next_state_comb[1] = 2'b01;
        next_state_comb[2] = 2'b10;
        next_state_comb[3] = 2'b11;
    end

    always @(*) begin
        case (state)
            2'b00: begin next_state = 2'b00; out = 1'b0; end
            2'b01: begin next_state = 2'b01; out = 1'b0; end
            2'b10: begin next_state = 2'b10; out = 1'b0; end
            2'b11: begin next_state = 2'b11; out = 1'b1; end
            default: begin next_state = 2'b00; out = 1'b0; end
        endcase
