            4'b0001: out <= 1'b0; next_state = in ? ns[1] : ns[0];
            4'b0010: out <= 1'b0; next_state = in ? ns[2] : ns[1];
            4'b0100: out <= 1'b0; next_state = in ? ns[0] : ns[2];
            4'b1000: out <= 1'b1; next_state = in ? ns[2] : ns[1];
            default: out <= 1'b0; next_state = ns[0];
